1	import type { Candidate, Inscription, Story } from '#lib/types.ts';
2	import type { PageText, RawFact } from './inference/index.ts';
3	
4	const MONTHS = new Set(
5		(
6			'january february march april may june july august september october november december ' +
7			'jan feb mar apr jun jul aug sep sept oct nov dec'
8		).split(' ')
9	);
10	
11	// Spelled-out numbers compare equal to their digits, so "forty" and "40" support each other.
12	// "one" is left out: "no one" and "one more time" are ordinary prose, not a count.
13	const NUMBER_VALUES: Record<string, string> = Object.fromEntries([
14		...'two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty'
15			.split(' ')
16			.map((w, i) => [w, String(i + 2)]),
17		['thirty', '30'],
18		['forty', '40'],
19		['fifty', '50'],
20		['sixty', '60'],
21		['seventy', '70'],
22		['eighty', '80'],
23		['ninety', '90'],
24		['hundred', '100'],
25		['thousand', '1000']
26	]);
27	
28	// Negations flip a claim, so one that touches a fact must come from that fact.
29	const NEGATIONS = new Set('not never no none nobody neither nor without cannot'.split(' '));
30	
31	// Words this short are filler; only longer words identify what a sentence is about.
32	const MIN_TOPIC_LENGTH = 5;
33	// Compare word stems so "preceded"/"preceding" match without a stemmer dependency.
34	const STEM_LENGTH = 5;
35	// A fact counts as used when at least this share of its topic words appear in the story.
36	const MIN_FACT_USE = 0.5;
37	
38	// A quote that names survivors would put living people's names into the story (FR-017).
39	const SURVIVORS =
40		/\b(survived by|survivors?|leaves behind|leaving behind|left to mourn|she leaves|he leaves)\b/i;
41	
42	/** A fact whose quote was found verbatim in a cited source. */
43	export type VerifiedFact = RawFact;
44	
45	/**
46	 * Lowercases and collapses everything except letters and digits to single spaces.
47	 * @param s Text to normalize.
48	 * @returns Normalized text.
49	 */
50	function norm(s: string): string {
51		return s
52			.toLowerCase()
53			.replace(/[^\p{L}\p{N}]+/gu, ' ')
54			.trim();
55	}
56	
57	/**
58	 * Maps a spelled-out number to its digits; any other word is returned unchanged.
59	 * @param word Lowercase word.
60	 * @returns Digits for a number word, else the word.
61	 */
62	function canon(word: string): string {
63		return NUMBER_VALUES[word] ?? word;
64	}
65	
66	/**
67	 * Lists the stems of a text's topic words, which say what the text is about.
68	 * @param text Normalized text.
69	 * @returns Stems of words long enough to carry meaning.
70	 */
71	function topicStems(text: string): string[] {
72		return text
73			.split(' ')
74			.filter((w) => w.length >= MIN_TOPIC_LENGTH)
75			.map((w) => canon(w).slice(0, STEM_LENGTH));
76	}
77	
78	/**
79	 * Keeps only facts whose quote appears verbatim in the source they cite and names no survivors.
80	 * @param candidate The confirmed candidate.
81	 * @param pages Text of each source as the model saw it.
82	 * @param raw Facts as the model returned them.
83	 * @returns Verified facts, without repeats.
84	 */
85	export function verifyFacts(
86		candidate: Candidate,
87		pages: PageText[],
88		raw: RawFact[]
89	): VerifiedFact[] {
90		const known = new Set(candidate.sources.map((s) => s.id));
91		const text = new Map(pages.map((p) => [p.sourceId, norm(p.text)]));
92		const seen = new Set<string>();
93		return raw.filter((f) => {
94			const quote = norm(f.quote ?? '');
95			if (!quote || !known.has(f.sourceId) || !text.get(f.sourceId)?.includes(quote)) return false;
96			if (SURVIVORS.test(f.quote)) return false;
97			if (seen.has(quote)) return false;
98			seen.add(quote);
99			return true;
100		});
101	}
102	
103	/**
104	 * Tokens of the person's own name, which a story may use without a quote.
105	 * @param inscription The stone's person.
106	 * @param candidate The confirmed candidate.
107	 * @returns Normalized name tokens.
108	 */
109	function nameTokens(inscription: Inscription, candidate: Candidate): Set<string> {
110		return new Set(
111			[inscription.name, candidate.name, inscription.maidenName ?? '']
112				.flatMap((n) => norm(n).split(' '))
113				.filter(Boolean)
114		);
115	}
116	
117	/**
118	 * Whether the facts say something beyond the person's name, months and bare numbers (FR-013).
119	 * @param inscription The stone's person.
120	 * @param candidate The confirmed candidate.
121	 * @param facts Verified facts.
122	 * @returns True when at least one "other" fact carries real content.
123	 */
124	export function hasEvidence(
125		inscription: Inscription,
126		candidate: Candidate,
127		facts: VerifiedFact[]
128	): boolean {
129		const names = nameTokens(inscription, candidate);
130		return facts.some(
131			(f) =>
132				f.claim === 'other' &&
133				norm(f.quote)
134					.split(' ')
135					.some((t) => !names.has(t) && !MONTHS.has(t) && !/^\d+$/.test(t))
136		);
137	}
138	
139	/**
140	 * Checks one sentence for claims the facts do not support: new numbers, new names, or a negation
141	 * attached to a fact. Atmosphere passes untouched.
142	 * @param sentence One sentence of the story.
143	 * @param quoteWords Normalized words of every fact quote.
144	 * @param quoteStems Per-fact topic stems, to tell which fact a sentence is about.
145	 * @param allowed Name and month tokens that need no quote.
146	 * @returns True when the sentence adds nothing the facts lack.
147	 */
148	function sentenceHolds(
149		sentence: string,
150		quoteWords: Set<string>,
151		quoteStems: { stems: Set<string>; words: Set<string> }[],
152		allowed: Set<string>
153	): boolean {
154		const words = sentence.match(/[\p{L}\p{N}]+/gu) ?? [];
155		const lower = words.map((w) => w.toLowerCase());
156		const topics = new Set(topicStems(lower.join(' ')));
157		const about = quoteStems.filter((q) => [...topics].some((t) => q.stems.has(t)));
158		for (const [i, word] of words.entries()) {
159			const w = lower[i];
160			const known = quoteWords.has(canon(w)) || allowed.has(w);
161			const number = /^\d+$/.test(w) || w in NUMBER_VALUES;
162			const properNoun = i > 0 && /^\p{Lu}/u.test(word) && w !== 'i';
163			if ((number || properNoun) && !known) return false;
164			if (NEGATIONS.has(w) && about.length > 0 && !about.some((q) => q.words.has(w))) return false;
165		}
166		return true;
167	}
168	
169	/**
170	 * Splits a paragraph into sentences.
171	 * @param paragraph Prose as the model wrote it.
172	 * @returns Trimmed, non-empty sentences.
173	 */
174	function sentencesOf(paragraph: string): string[] {
175		return paragraph
176			.split(/(?<=[.!?…])\s+/u)
177			.map((s) => s.trim())
178			.filter(Boolean);
179	}
180	
181	/**
182	 * Drops sentences that add claims the verified facts do not support, then checks the story still
183	 * uses the facts and lists the sources it draws on.
184	 * @param inscription The stone's person.
185	 * @param candidate The confirmed candidate.
186	 * @param facts Verified facts the paragraph was written from.
187	 * @param paragraph The paragraph as the model wrote it.
188	 * @returns A told story, or `insufficient` when no real fact survives in it.
189	 */
190	export function groundParagraph(
191		inscription: Inscription,
192		candidate: Candidate,
193		facts: VerifiedFact[],
194		paragraph: string
195	): Story {
196		if (!hasEvidence(inscription, candidate, facts)) return { status: 'insufficient' };
197		const normed = facts.map((f) => norm(f.quote));
198		const quoteWords = new Set(normed.flatMap((q) => q.split(' ').map(canon)));
199		const quoteStems = normed.map((q) => ({
200			stems: new Set(topicStems(q)),
201			words: new Set(q.split(' '))
202		}));
203		const allowed = new Set([...nameTokens(inscription, candidate), ...MONTHS]);
204	
205		const seen = new Set<string>();
206		const kept = sentencesOf(paragraph).filter((s) => {
207			const key = norm(s);
208			if (seen.has(key)) return false;
209			seen.add(key);
210			return sentenceHolds(s, quoteWords, quoteStems, allowed);
211		});
212		const body = kept.join(' ');
213	
214		const present = new Set(topicStems(norm(body)));
215		const used = facts.filter((f, i) => {
216			const stems = [...quoteStems[i].stems];
217			return (
218				stems.length > 0 && stems.filter((s) => present.has(s)).length / stems.length >= MIN_FACT_USE
219			);
220		});
221		if (!hasEvidence(inscription, candidate, used)) return { status: 'insufficient' };
222		const cited = new Set(used.map((f) => f.sourceId));
223		return {
224			status: 'told',
225			paragraph: body,
226			sources: candidate.sources.filter((s) => cited.has(s.id))
227		};
228	}
